import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $b = {base}$ be an integer base. The diameter $AB$ of a circle has a length $D$ which is a two-digit number when written in base $b$. Let the digits be $t$ and $u$, so $D = t \\cdot b + u$, where $t \\in \\{1, 2, \\dots, b-1\\}$ and $u \\in \\{0, 1, \\dots, b-1\\}$. Reversing the digits of $D$ in base $b$ gives the length of a chord $CD$, which is perpendicular to the diameter $AB$. The distance from the intersection point of $AB$ and $CD$ to the center of the circle is a positive integer. Find the sum of all possible values of $D$, expressed as an integer in base 10.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We choose bases for which there are a reasonable number of solutions (2-4).
# Pre-calculated good bases for the 'integer distance' constraint.
# b=7 -> 3 solutions
# b=9 -> 3 solutions
# b=26, with m even, gives 6 solutions, a bit high.
# Let's stick to simple, elegant cases.
good_bases = [7, 9]
base = rng.choice(good_bases)
return {'base': base}

    def verifier(assign):
b = assign['base']

# The base must be an integer greater than 1.
if not isinstance(b, int) or b <= 1:
    return False, None

def get_square_free_part(n):
    if n <= 0:
        return 0
    sf = 1
    i = 2
    temp_n = n
    while i * i <= temp_n:
        count = 0
        while temp_n % i == 0:
            count += 1
            temp_n //= i
        if count % 2 == 1:
            sf *= i
        i += 1
    if temp_n > 1:
        sf *= temp_n
    return sf

s_val = b * b - 1
s_sf = get_square_free_part(s_val)
s_sq_part_sqrt = int((s_val / s_sf)**0.5)

total_d = 0
solution_count = 0

for t in range(1, b):
    for u in range(0, t):
        # Condition for h to be rational: (b^2-1)(t^2-u^2) must be a perfect square.
        # This implies sf(b^2-1) == sf(t^2-u^2).
        t_u_val = t * t - u * u
        if t_u_val == 0:
            continue

        t_u_sf = get_square_free_part(t_u_val)

        if s_sf == t_u_sf:
            # We have a rational h. Now check if h is an integer.
            # 4h^2 = (b^2-1)(t^2-u^2) = (s_sf * s_sq_part_sqrt^2) * (t_u_sf * t_u_sq_part_sqrt^2)
            # 4h^2 = s_sf^2 * (s_sq_part_sqrt * t_u_sq_part_sqrt)^2
            # 2h = s_sf * s_sq_part_sqrt * t_u_sq_part_sqrt
            t_u_sq_part_sqrt = int((t_u_val / t_u_sf)**0.5)

            two_h = s_sf * s_sq_part_sqrt * t_u_sq_part_sqrt

            # For h to be an integer, 2h must be an even integer.
            if two_h > 0 and two_h % 2 == 0:
                d = t * b + u
                total_d += d
                solution_count += 1

# The problem should not be trivial.
if solution_count < 2:
    # This indicates a problem with the generator's chosen base.
    # The pre-selected bases should not trigger this.
    return False, None

return True, total_d


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
